import pandas as pd, numpy as np
from scipy.optimize import least_squares
exec(open('/dev/null').read())
def sim(p,d):
    Kq,Tq,Kqd,Kp,Tw,Kpv,Kqw=p
    V=d.voltage_pu.values; th=d.bus_angle_rad.values; Vs=d.voltage_setpoint_pu.values
    P0,Q0=d.active_power_pu.values[0],d.reactive_power_pu.values[0]
    V0=V[0]; dt=d.time_s.values[1]-d.time_s.values[0]
    n=len(V); Pm=np.zeros(n); Qm=np.zeros(n)
    xq=Q0; xt=0.0
    for i in range(n):
        Qm[i]=xq+Kqd*(V[i]-V0)-Kqw*(th[i]-xt)
        Pm[i]=P0-Kp*(th[i]-xt)+Kpv*(V[i]-V0)
        if i>0:
            xq+=dt*(Q0+Kq*(Vs[i]-V[i])-xq)/Tq
            xt+=dt*(th[i]-xt)/Tw
    return Pm,Qm
files=['train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_line_op3.csv','train/A_fault_op1.csv']
ds={f:pd.read_csv(f).iloc[::10].reset_index(drop=True) for f in files}
def res(p,fs):
    out=[]
    for f in fs:
        dd=ds[f]; Pm,Qm=sim(p,dd)
        out+=[Pm-dd.active_power_pu.values, Qm-dd.reactive_power_pu.values]
    return np.concatenate(out)
best=None
for Tw0 in [0.02,0.1,0.5]:
  for Kq0 in [1,3,8]:
    for Tq0 in [0.05,0.3,1.0]:
        p0=[Kq0,Tq0,1.6,0.4,Tw0,-0.05,0.0]
        try:
            r=least_squares(res,p0,args=(files,),bounds=([-50,1e-3,-50,-50,1e-3,-50,-50],[50,5,50,50,1e3,50,50]),max_nfev=200)
        except Exception as e: continue
        c=np.sqrt(np.mean(r.fun**2))
        if best is None or c<best[0]: best=(c,r.x)
        print(round(c,5),np.round(r.x,4))
print('BEST',best)
np.save('pbest.npy',best[1])

